$('#examples').onchange=e=>{const ex=examples[e.target.value];if(!ex)return;checkpoint();q=clone(ex);selected=null;setTool('select');syncSettings();changed();e.target.value=''};
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async()=>{try{const file=$('#file').files[0];if(!file)return;if(file.size>4000000)throw Error('The file exceeds 4 MB.');const data=JSON.parse(await file.text());if(data.format==='gentle-session-v2'){if(!Array.isArray(data.algebras)||!data.algebras.length||data.algebras.length+algebras.length>40||!data.algebras.every(a=>validFile(a.quiver)))throw Error('Invalid session or more than 40 algebra tabs.');const incoming=data.algebras.map(a=>blankState(a.quiver,a.characteristic,a.degree));algebras.push(...incoming);await switchAlgebra(incoming[0].id);toast('Session opened in new algebra tabs.')}else{const incoming=data.quiver||data;if(!validFile(incoming))throw Error('This is not a supported quiver JSON file.');const copy=clone(incoming);copy.vertices.forEach(v=>{v.x=Math.max(30,Math.min(770,v.x));v.y=Math.max(70,Math.min(380,v.y))});await addAlgebra(copy,data.characteristic??characteristic,data.degree??degree);toast('Quiver opened in a new tab.')}}catch(e){toast(e.message)}finally{$('#file').value=''}};
$('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;if(tab==='surface'&&$('[data-surface]'))mountSurfaceFigures(surfaceComponents(q));try{localStorage.setItem('gentle-theme',theme)}catch{}$('#theme').setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} mode`)};
window.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea,dialog'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();history(!e.shiftKey);return}if(e.key==='Escape'){setTool('select');return}if(e.key==='Delete'&&selected){erase(selected.type,selected.id);return}if(!e.ctrlKey&&!e.metaKey&&!e.altKey){const t={v:'select',n:'vertex',a:'arrow',r:'relation',d:'delete'}[e.key.toLowerCase()];if(t)setTool(t)}});
async function compute(){stopWorker();report=null;operations=[];dirty=true;renderResults();setBusy(true);$('#progress').textContent='Building exact chain complexes…';try{const r=await call('compute',{quiver:q,characteristic,degree});report=r;if(derived)report.derived=derived;dirty=false;selectedDegree=Math.min(selectedDegree,degree);renderResults();$('#progress').textContent=r.mode==='formulas'?'Complete using circuit formulas. Representatives exceeded the resource limit.':'Complete. All displayed checks passed.';save()}catch(e){$('#progress').textContent=e.message;if(e.message!=='Computation cancelled.')renderError(e.message)}finally{setBusy(false)}}
$('#compute').onclick=compute;$('#cancel').onclick=()=>{stopWorker();dirty=true;$('#progress').textContent='Computation cancelled. Your quiver is preserved.';renderResults()};
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$$('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-current',x===b?'page':'false')});renderResults()});
function terms(items){const path=p=>`<span class="path-value" title="${p.type==='idempotent'?'Vertex idempotent':'Surviving path'}">${esc(p.notation||p.label)}<small>${p.type==='idempotent'?'idempotent':'path'}</small></span>`;return items.length?items.map((x,i)=>x.form==='central-element'?`<span class="term central-element">${i?'+ ':''}<strong class="cochain-output">${x.coefficient==='1'?'':`${esc(x.coefficient)} · `}${esc(x.output.notation||x.output.label)}</strong></span>`:x.output?`<span class="term">${x.summand===null?'':`C<sub>${x.summand}</sub>: `}${x.kind==='co'?`<span class="cochain-input">[${x.input.map(path).join(' | ')}]</span> <span class="cochain-mapsto">↦</span> <strong class="cochain-output"><span class="term-coefficient">${esc(x.coefficient)} · </span>${path(x.output)}</strong>`:`<span class="term-coefficient">${esc(x.coefficient)} · </span><strong class="chain-leading">${path(x.output)}</strong> [${x.input.map(path).join(' | ')}]`}</span>`:`<span class="term">${esc(x.coefficient)} · ${esc(x.term)}</span>`).join(''):'0'}
function formula(cs,kind,n){const symbol=kind==='co'?`h<sup>${n}</sup>`:`z<sub>${n}</sub>`;const parts=cs.flatMap((c,i)=>c==='0'?[]:[`${esc(c)} ${symbol}<sub>${i+1}</sub>`]);return parts.length?parts.join(' + ').replace(/\+ -/g,'− '):'0'}
function tableRows(){return `<div class="table-wrap"><table><thead><tr><th>Degree n</th><th>dim HH<sup>n</sup></th><th>dim HH<sub>n</sub></th><th>dim HC<sub>n</sub></th></tr></thead><tbody>${report.rows.map(r=>`<tr><td>${r.degree}</td><td>${r.hhCo}</td><td>${r.hhHo}</td><td>${r.hc}</td></tr>`).join('')}</tbody></table></div>`}
function renderError(message){$('#results').innerHTML=`<div class="notice error">${esc(message)}</div><p class="micro">No incomplete calculation is reported as a zero group. Try a smaller degree range.</p>`}
function renderResults(){
 if(tab==='surface'){$('#result-status').textContent='Marked surface and ribbon graph';const errors=validate(q);try{if(errors.length)throw Error(errors.join(' '));renderSurface()}catch(e){$('#results').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}return}
 if(tab==='derived'){renderDerived();return}
 $('#result-status').textContent=dirty?'Recompute after changing the algebra or field.':`char k = ${report?.characteristic} · degrees 0–${report?.maxDegree} · ${report?.mode==='formulas'?'circuit formulas':'checked'}`;
 if(!report||dirty){$('#results').innerHTML=`<div class="empty-results"><div class="empty-symbol">HH<sup>∗</sup>(A)</div><h3>${report?'Your algebra has changed.':'The next step is a calculation.'}</h3><p>${report?'Compute again to update the groups and operations.':'Draw a quiver, set its zero relations, and select Compute calculus.'}</p><p>Groups, representatives, and operations will appear here.</p></div>`;return}
 if(report.mode==='formulas'&&['cohomology','homology','cyclic','operations'].includes(tab)){renderFormulaOnly();return}
 if(tab==='overview')renderOverview();else if(['cohomology','homology','cyclic'].includes(tab))renderBasis();else if(tab==='operations')renderOperations();else if(tab==='structure')renderStructure();else if(tab==='all')renderAllDegrees();else if(tab==='surface')renderSurface();else if(tab==='lie')renderLie();else renderChecks();
}
function renderOverview(){const r=report,s=r.structure;$('#results').innerHTML=`<div class="metric-grid"><div class="metric"><div class="metric-label">Algebra dimension</div><div class="metric-value">${r.algebraDimension}</div><div class="metric-foot">Paths surviving the relations</div></div><div class="metric"><div class="metric-label">Center · HH⁰(A)</div><div class="metric-value">${r.rows[0].hhCo}</div><div class="metric-foot">Dimension over the chosen field</div></div><div class="metric"><div class="metric-label">Global dimension</div><div class="metric-value">${s.globalDimension}</div><div class="metric-foot">${s.cycles.length?'Complete relation circuits present':'Longest forbidden path'}</div></div><div class="metric"><div class="metric-label">Complete primitive circuits</div><div class="metric-value">${s.cycles.length}</div><div class="metric-foot">Up to cyclic rotation</div></div></div><div class="overview-bottom"><div class="result-card"><h3>Dimensions by degree</h3>${tableRows()}</div><div class="result-card"><h3>${r.mode==='formulas'?'Exact circuit formulas':'A checked calculation'}</h3><div class="checked-line"><b>✓</b> Exact ${r.characteristic==='0'?'rational':'prime-field'} arithmetic throughout.</div>${r.mode==='formulas'?`<div class="notice">${esc(r.limitation)} Dimensions below remain exact; bar representatives are unavailable.</div>`:'<div class="checked-line"><b>✓</b> Bar and Bardzell resolutions agree.</div><div class="checked-line"><b>✓</b> Differential and mixed-complex identities verified.</div>'}<p>${r.mode==='formulas'?'Reduce the degree range to try materializing representatives. The all-degree, ring and surface panels remain available.':'Open a group to inspect its basis. Use Operations to calculate with linear combinations of these classes.'}</p><a class="text-link" href="https://arxiv.org/html/2311.08003v4" target="_blank" rel="noreferrer">Read the mathematical source ↗</a></div></div>`}
function renderBasis(){const kind=tab==='cohomology'?'co':tab==='homology'?'ho':'cyclic',r=report.rows[selectedDegree],basis=kind==='co'?r.coBasis:kind==='ho'?r.hoBasis:r.cyBasis,symbol=kind==='co'?`HH<sup>${selectedDegree}</sup>`:kind==='ho'?`HH<sub>${selectedDegree}</sub>`:`HC<sub>${selectedDegree}</sub>`;$('#results').innerHTML=`<div class="basis-top"><p>${kind==='co'?'Cocycles modulo coboundaries.':kind==='ho'?'Cycles modulo boundaries.':'Homology of the cyclic total complex (C, b, B).'}<br>Expand a class to inspect its representative.</p><label class="degree-select">Degree <select id="basis-degree">${report.rows.map(x=>`<option value="${x.degree}" ${x.degree===selectedDegree?'selected':''}>${x.degree}</option>`).join('')}</select></label></div><div class="notice">${symbol}(A) ≅ k<sup>${basis.length}</sup>. ${kind==='co'&&selectedDegree===0?'HH⁰(A) = Z(A). Representatives are displayed as central elements of A.':kind==='cyclic'?'The prefix Cₖ identifies the summand in the cyclic total complex.':'Representatives use the normalized relative bar complex; unlisted values of cochains are zero.'}</div>${basis.length?basis.map((b,i)=>`<details class="basis-card" ${basis.length<=3?'open':''}><summary><span class="basis-label">${kind==='co'?`h<sup>${selectedDegree}</sup>`:kind==='ho'?`z<sub>${selectedDegree}</sub>`:`c<sub>${selectedDegree}</sub>`}<sub>${i+1}</sub></span> Basis class ${i+1}</summary><div class="representative">${terms(b)}</div></details>`).join(''):`<div class="zero-space">${symbol}(A) = 0<small>The entire cycle space is the boundary space in this degree.</small></div>`}`;$('#basis-degree').onchange=e=>{selectedDegree=Number(e.target.value);renderBasis()};if(kind==='cyclic')$('#results').insertAdjacentHTML('beforeend',`<div class="result-card" style="margin-top:18px"><h3>Connes and noncommutative de Rham homology</h3><p>Hᵈᴿₙ = ker Bₙ / im Bₙ₋₁. These dimensions use Proposition 4.12. The rank is for Bₙ : HHₙ → HHₙ₊₁.</p><div class="table-wrap"><table><thead><tr><th>Degree</th><th>rank Bₙ</th><th>dim Hᵈᴿₙ</th></tr></thead><tbody>${report.rows.map(x=>`<tr><td>${x.degree}</td><td>${x.connesRank}</td><td>${x.deRham}</td></tr>`).join('')}</tbody></table></div>${report.rows.filter(x=>x.connesMatrix).map(x=>`<details class="basis-card"><summary>Degree ${x.degree} · Connes matrix and de Rham representatives</summary>${x.connesMatrix.map((cs,i)=>`<p>B(z<sub>${x.degree},${i+1}</sub>) = ${formula(cs,'ho',x.degree+1)}</p>`).join('')}<h3 style="margin-top:12px">De Rham basis in HH<sub>${x.degree}</sub></h3>${x.deRhamBasis.map(cs=>`<p>${formula(cs,'ho',x.degree)}</p>`).join('')||'<p>This de Rham group is zero.</p>'}</details>`).join('')}</div>`) }
function coefficientCard(side,kind,n){const r=report.rows[n],basis=kind==='co'?r.coBasis:r.hoBasis;return `<div class="result-card"><h3>${side==='left'?'First':'Second'} class · ${kind==='co'?`HH<sup>${n}</sup>`:`HH<sub>${n}</sub>`}(A)</h3><p>Enter a coefficient for each basis class.</p><div class="coeff-list">${basis.length?basis.map((b,i)=>`<div class="coeff-row"><label for="${side}-${i}" title="${esc(b.map(x=>x.coefficient+' '+x.term).join(' + '))}">${kind==='co'?`h<sup>${n}</sup>`:`z<sub>${n}</sub>`}<sub>${i+1}</sub></label><input id="${side}-${i}" data-coeff="${side}" value="${esc(op.coefficients?.[side]?.[i]??(i===0?'1':'0'))}" aria-label="Coefficient of ${side} basis class ${i+1}" spellcheck="false"></div>`).join(''):'<p>This group is zero; its only element is 0.</p>'}</div><details><summary class="micro">View basis representatives</summary>${basis.map((b,i)=>`<div class="representative"><b>${i+1}.</b> ${terms(b)}</div>`).join('')}</details></div>`}
function renderOperations(){op.p=Math.min(op.p,report.maxDegree);op.q=Math.min(op.q,report.maxDegree);const options=n=>report.rows.map(x=>`<option value="${x.degree}" ${x.degree===n?'selected':''}>${x.degree}</option>`).join('');$('#results').innerHTML=`<div class="operation-controls"><label for="op-type">Operation</label><select id="op-type"><option value="cup">Cup product ∪</option><option value="bracket">Gerstenhaber bracket [−,−]</option><option value="cap">Cap product ⌢</option><option value="connes">Connes operator B</option><option value="lie">Lie derivative L</option></select><label for="op-p">${op.type==='connes'?'Input degree':'First degree'}</label><select id="op-p">${options(op.p)}</select>${op.type!=='connes'?`<label for="op-q">Second degree</label><select id="op-q">${options(op.q)}</select>`:''}</div><div class="notice">Coefficients are exact integers or fractions (for example, −2 written as -2, or 3/5). The result is reduced modulo boundaries. Output degrees are computed on demand, subject to the resource limits.</div><div class="operation-grid">${coefficientCard('left',op.type==='connes'?'ho':'co',op.p)}${op.type!=='connes'?coefficientCard('right',['cap','lie'].includes(op.type)?'ho':'co',op.q):'<div class="result-card"><h3>The Connes boundary</h3><p>B : HHₙ(A) → HHₙ₊₁(A)</p><p>The operator is evaluated by cyclic rotation in the normalized chain complex and then projected onto the homology basis.</p></div>'}</div><button id="run-operation" class="primary-button operation-run">Calculate <span>→</span></button><div id="operation-output" aria-live="polite"></div><div class="operation-log"><h3>Calculation history</h3>${operations.length?operations.map((x,i)=>`<details><summary>${i+1}. ${esc(x.type)} · degrees ${x.p}${x.type==='connes'?'':', '+x.q}</summary><div class="representative">Input: ${esc(x.left.join(', '))}${x.type==='connes'?'':' ; '+esc(x.right.join(', '))}</div><p>${formula(x.result.coefficients,x.result.kind,x.result.degree)}</p></details>`).join(''):'<p class="micro">Operations from this algebra will be included in the LaTeX export.</p>'}</div>`;$('#op-type').value=op.type;$('#op-type').onchange=e=>{op.type=e.target.value;delete op.coefficients;renderOperations()};$('#op-p').onchange=e=>{op.p=Number(e.target.value);delete op.coefficients;renderOperations()};if($('#op-q'))$('#op-q').onchange=e=>{op.q=Number(e.target.value);delete op.coefficients;renderOperations()};$('#run-operation').onclick=runOperation}
async function runOperation(){const button=$('#run-operation'),left=$$('[data-coeff=left]').map(x=>x.value),right=$$('[data-coeff=right]').map(x=>x.value),input={...op,left,right};button.disabled=true;setBusy(true);try{const result=await call('operation',{operation:op.type,p:op.p,q:op.q,left,right});const basis=await call('group',{kind:result.kind,degree:result.degree});operations.push({...input,result,outputBasis:basis});if(tab==='operations'&&!dirty){renderOperations();$('#operation-output').innerHTML=`<div class="operation-result"><h3>RESULT · ${result.kind==='co'?'COHOMOLOGY':'HOMOLOGY'} DEGREE ${result.degree}</h3><div class="formula">${formula(result.coefficients,result.kind,result.degree)}</div><details><summary class="micro">Result representative</summary><div class="representative">${terms(result.representative)}</div></details><details><summary class="micro">Output basis (${basis.dimension} classes)</summary>${basis.basis.map((b,i)=>`<div class="representative"><b>${i+1}.</b> ${terms(b)}</div>`).join('')||'<p class="micro">Zero group.</p>'}</details></div>`}}catch(e){if($('#operation-output'))$('#operation-output').innerHTML=`<div class="notice error" style="margin-top:15px">${esc(e.message)}</div>`}finally{button.disabled=false;setBusy(false);$('#progress').textContent=''}}
function renderStructure(){const s=report.structure;$('#results').innerHTML=`<div class="structure-grid"><div class="result-card"><h3>The presentation</h3><p>${s.components} connected component${s.components===1?'':'s'} · Euler characteristic of Q: ${s.euler}<br>Underlying graph cycle rank: ${s.cycleRank}<br>Global dimension: ${s.globalDimension}</p><h3 style="margin-top:20px">Arrows outside a spanning forest</h3><div class="pill-list">${s.chords.map(esc).map(x=>`<span class="pill">${x}</span>`).join('')||'<span class="micro">None</span>'}</div></div><div class="result-card"><h3>Complete primitive circuits</h3>${s.cycles.length?s.cycles.map(c=>`<p><span class="math">${esc(c.label)}</span> · length ${c.length}<br>Polynomial cohomology family starts in degree ${report.characteristic==='2'||c.length%2===0?c.length:2*c.length}.</p>`).join(''):'<p>None. The algebra has finite global dimension.</p>'}<p style="margin-top:12px">Every consecutive pair, including the wraparound pair, is a zero relation. These circuits determine the persistent higher-degree families.</p></div><div class="result-card"><h3>Maximal permitted paths</h3><div class="pill-list">${s.permitted.map(x=>`<span class="pill">${esc(x)}</span>`).join('')||'<span class="micro">No positive-length paths.</span>'}</div></div><div class="result-card"><h3>Maximal finite forbidden paths</h3><div class="pill-list">${s.forbidden.map(x=>`<span class="pill">${esc(x)}</span>`).join('')||'<span class="micro">None outside the complete circuits.</span>'}</div></div><div class="result-card"><h3>Path basis of A</h3><div class="pill-list">${report.paths.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div></div><div class="result-card"><h3>Path-count matrix</h3><p>Row = source; column = target. Entries count surviving paths.</p><div class="table-wrap"><table><thead><tr><th></th>${s.vertices.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${s.cartan.map((row,i)=>`<tr><th>${esc(s.vertices[i])}</th>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="result-card wide"><h3>Query a higher degree with the small resolution</h3><p>Bardzell’s resolution can compute groups beyond the displayed range without constructing the bar complex. These representatives use a different basis from the Operations tab.</p><div class="operation-controls" style="margin-top:15px"><label for="high-kind">Group</label><select id="high-kind"><option value="co">Hochschild cohomology</option><option value="ho">Hochschild homology</option></select><label for="high-degree">Degree</label><input id="high-degree" type="number" min="0" max="128" value="12"><button id="high-query" class="small-button">Compute group</button></div><div id="high-result" aria-live="polite"></div></div></div>`;$('#high-query').onclick=async()=>{const n=Number($('#high-degree').value),kind=$('#high-kind').value;if(!Number.isInteger(n)||n<0||n>128){toast('Choose a degree from 0 to 128.');return}const b=$('#high-query');b.disabled=true;setBusy(true);try{const g=await call('group',{kind,degree:n,model:'bardzell'});(report.additionalGroups??=[]).push(g);if($('#high-result'))$('#high-result').innerHTML=`<div class="notice">Dimension ${g.dimension} in degree ${g.degree}. Differential-square check passed.</div>${g.basis.map((v,i)=>`<details class="basis-card"><summary>Class ${i+1}</summary><div class="representative">${terms(v)}</div></details>`).join('')}`}catch(e){if($('#high-result'))$('#high-result').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{b.disabled=false;setBusy(false)}}}
function renderChecks(){$('#results').innerHTML=`<div class="method-grid"><div class="result-card"><h3>Checks for this calculation</h3>${report.checks.map(x=>`<div class="check-row"><span>✓</span>${esc(x)}</div>`).join('')}<p style="margin-top:16px">These are algebraic consistency checks, not a proof that the implementation has no errors. The test suite also checks known examples and characteristic-dependent operations.</p></div><div class="result-card"><h3>Conventions & scope</h3><p>${esc(report.convention)}</p><p>The paper writes paths right to left. This workspace uses travel order: α·β means follow α, then β. Translate this path to βα in the paper.</p><p>The chosen characteristic uses ℚ or 𝔽ₚ. Dimensions and structure constants extend to any field of the same characteristic; coefficients from non-prime field extensions are not accepted.</p><p>${report.mode==='formulas'?'Displayed dimensions use the all-degree circuit formulas; bar differentials and representatives were not completed.':'Displayed groups are complete in each computed degree, with the adjacent differentials included.'} Resource limits: 200 algebra paths, 900 vectors per chain space, 1.1 million matrix entries, and degree 128. A limit produces an error, never a fabricated zero.</p><p>All degrees & ring gives a finite description of the infinite cohomology families and the ring presentation. Surface gives the combinatorial ribbon graph, boundary winding numbers, and AAG invariant. Operations use explicit bar representatives within resource limits; there is no symbolic polynomial-expression parser or interactive surface-curve editor.</p><a class="text-link" href="METHODOLOGY.md" target="_blank">Detailed methods and theorem coverage ↗</a></div><div class="result-card" style="grid-column:1/-1"><h3>Complex dimensions and boundary ranks</h3><div class="table-wrap"><table><thead><tr><th>n</th><th>dim Cⁿ</th><th>rank δⁿ⁻¹</th><th>dim HHⁿ</th><th>dim Cₙ</th><th>rank bₙ₊₁</th><th>dim HHₙ</th></tr></thead><tbody>${report.rows.map(r=>`<tr><td>${r.degree}</td><td>${r.coSize}</td><td>${r.coBoundaryRank}</td><td>${r.hhCo}</td><td>${r.hoSize}</td><td>${r.hoBoundaryRank}</td><td>${r.hhHo}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function modal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}};
$('#help').onclick=()=>modal('A short guide',`<ol><li><b>Draw the quiver.</b> Choose Vertex and tap the canvas. Choose Arrow and tap its source, then its target. Tap the same vertex twice for a loop.</li><li><b>Set the relations.</b> Choose Relation and tap two consecutive arrows. Their left-to-right product becomes zero. A loop may be selected twice.</li><li><b>Make it yours.</b> Select a vertex or arrow to rename it. Drag vertices to arrange the diagram. Use Undo to recover edits.</li><li><b>Compute.</b> Select the field characteristic and degree range. Inspect groups, expand representatives, or calculate products of classes in Operations.</li><li><b>Keep your work.</b> Export the quiver as JSON, results as JSON, or the calculation as a standalone LaTeX document.</li></ol><p>Keyboard tools: V select, N vertex, A arrow, R relation, D delete. Ctrl/Cmd Z undoes. Tab focuses diagram items; Enter selects them. Arrow keys move a focused vertex.</p><p>All computations and saved work stay in this browser. No account or server is needed. Read <a href="METHODOLOGY.md" target="_blank">Methods & scope</a> for mathematical conventions and current coverage.</p>`);
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export').onclick=()=>{modal('Export your workspace',`<p>Session JSON saves every open quiver and its field and degree settings. Computations are rebuilt after reopening.</p><button id="export-session" class="outline-button">All algebra tabs · JSON <span>↓</span></button><button id="export-quiver" class="outline-button">Current quiver · JSON <span>↓</span></button><button id="export-results" class="outline-button" ${!report||dirty?'disabled':''}>Results, representatives & operations · JSON <span>↓</span></button><button id="export-tex" class="outline-button" ${!report||dirty?'disabled':''}>Mathematical report · LaTeX (.tex) <span>↓</span></button><p>Compute the calculus for report exports. The Complete derived invariant panel also exports its invariant and comparison directly, without a calculus calculation. Compile LaTeX with LuaLaTeX.</p>`);$('#export-session').onclick=()=>download('gentle-session.json',JSON.stringify(sessionData(),null,2),'application/json');$('#export-quiver').onclick=()=>download('gentle-quiver.json',JSON.stringify({format:'gentle-quiver-v1',quiver:q,characteristic,degree},null,2),'application/json');$('#export-results').onclick=()=>download('gentle-results.json',JSON.stringify({format:'gentle-results-v1',quiver:q,report,operations,derived,comparison:currentComparison()},null,2),'application/json');$('#export-tex').onclick=()=>download('gentle-calculus.tex',latexReport(q,{...report,derived,comparison:currentComparison()},operations),'application/x-tex')};
try{const saved=JSON.parse(localStorage.getItem('gentle-session-v2'));if(saved?.format==='gentle-session-v2'&&Array.isArray(saved.algebras)&&saved.algebras.length&&saved.algebras.length<=40&&saved.algebras.every(a=>validFile(a.quiver))){algebras=saved.algebras.map(a=>({...blankState(a.quiver,a.characteristic,a.degree),id:typeof a.id==='string'&&/^[a-zA-Z0-9-]+$/.test(a.id)?a.id:crypto.randomUUID()}));if(new Set(algebras.map(a=>a.id)).size!==algebras.length)algebras.forEach(a=>a.id=crypto.randomUUID());activate(algebras.find(a=>a.id===saved.activeId)||algebras[0])}}catch{}
syncSettings();renderSetup();draw();renderResults();save();
if(!validate(q).length)compute();

new ResizeObserver(()=>draw()).observe($('#quiver'));

const branchName=c=>c.branch==='genus-zero'?'Genus zero: boundary data are complete':c.branch==='genus-one'?`Genus one: gcd = ${c.gcd}`:c.branch==='odd-winding'?'An odd winding number occurs':c.branch==='even-boundary-zero-mod-four'?'All windings even; a boundary winding is 0 mod 4':`All windings even; boundary windings are 2 mod 4; Arf = ${c.arf}`;
function derivedCards(d){return `<div class="derived-components">${d.components.map((c,i)=>`<div class="result-card"><h3>Component ${i+1} · genus ${c.genus}</h3><p>${esc(branchName(c))}</p><p class="micro">${c.ordinaryBoundaries} marked boundary component(s), ${c.punctures} puncture(s), ${c.markedPoints} ○-marked points. Vertices: ${c.vertices.map(esc).join(', ')}.</p><div class="table-wrap"><table><thead><tr><th>Boundary / puncture</th><th>Marked points n</th><th>Forbidden length m</th><th>APS winding n−m</th></tr></thead><tbody>${c.boundaries.map((b,j)=>`<tr><td>${j+1}${b.markedPoints?'':' (puncture)'}</td><td>${b.markedPoints}</td><td>${b.forbiddenLength}</td><td>${b.winding}</td></tr>`).join('')}</tbody></table></div><details class="derived-evidence"><summary>Inspect cycle windings and intersection form</summary><p class="micro">A spanning-tree cycle basis of H₁ of the punctured surface. These curves need not be a symplectic basis. Walk entries name ribbon edges, which are quiver vertices.</p><div class="table-wrap"><table><thead><tr><th>Cycle</th><th>Edge walk</th><th>Local turns</th><th>Winding</th></tr></thead><tbody>${c.curves.map(v=>`<tr><td>${esc(v.name)}</td><td>${v.walk.map(e=>`${esc(e.edge)} (${e.from}→${e.to})`).join(', ')}</td><td>${v.turns.join(', ')}</td><td>${v.winding}</td></tr>`).join('')||'<tr><td colspan="4">No cycles.</td></tr>'}</tbody></table></div><h3>Intersection matrix over 𝔽₂</h3><pre class="derived-signature">${c.intersection.map(row=>row.join(' ')).join('\n')||'Empty matrix'}</pre>${c.quadratic?`<p>Quadratic form q(γ) = w(γ)/2 + 1 mod 2. After symplectic reduction, pairs (q(aᵢ), q(bᵢ)) are ${c.quadratic.pairs.map(p=>`(${p.qa}, ${p.qb})`).join(', ')}. Their product sum is ${c.arf} mod 2. The quadratic form vanishes on the radical.</p>`:''}</details><details class="derived-evidence"><summary>Canonical component signature</summary><pre class="derived-signature">${esc(JSON.stringify(c.signature,null,2))}</pre></details></div>`).join('')}</div>`}
function currentComparison(){if(!comparison)return null;for(const side of [comparison.left,comparison.right]){const a=side.id===activeId?{q,characteristic}:algebras.find(a=>a.id===side.id);if(!a||a.characteristic!==side.characteristic||JSON.stringify(a.q)!==JSON.stringify(side.quiver))return null}return comparison}
function renderDerived(){
 $('#result-status').textContent='Complete derived invariant · APS Theorem 7.4';
 const errors=validate(q),others=algebras.filter(a=>a.id!==activeId),previous=currentComparison();
 $('#results').innerHTML=`<div class="notice">Compute the complete derived invariant directly from the quiver. It includes genus, boundary and puncture data, and the required gcd, parity or Arf invariant. <a href="https://doi.org/10.1007/s00029-022-00822-x" target="_blank" rel="noreferrer">Amiot–Plamondon–Schroll, Theorem 7.4 ↗</a></div><div class="derived-controls"><button id="compute-derived" class="small-button" ${errors.length||busy?'disabled':''}>${derived?'Recompute':'Compute'} derived invariant</button>${derived?'<button id="derived-json" class="outline-button">Invariant · JSON ↓</button><button id="derived-tex" class="outline-button">Invariant & comparison · LaTeX ↓</button>':''}</div>${errors.length?`<p class="notice error">${errors.map(esc).join(' ')}</p>`:''}<div id="derived-output" aria-live="polite">${derived?derivedCards(derived):'<p class="micro">No Hochschild degree bound or bar-complex calculation is needed.</p>'}</div><div class="result-card"><h3>Compare with another algebra tab</h3><p>Compare bounded derived categories over the same ground field. Equal component signatures give derived equivalence, including for disconnected algebras.</p><div class="derived-controls"><label for="compare-target">Other algebra</label><select id="compare-target" ${!others.length?'disabled':''}>${others.map(a=>`<option value="${a.id}">${esc(a.q.name||'Untitled algebra')} · char ${esc(a.characteristic||'?')}</option>`).join('')||'<option>Open or duplicate an algebra tab first</option>'}</select><button id="compare-derived" class="small-button" ${!others.length||errors.length||busy?'disabled':''}>Check derived equivalence</button></div><div id="comparison-output" aria-live="polite">${previous?comparisonHTML(previous):comparison?'<p class="micro">A compared presentation or field has changed. Compare again to update the result.</p>':''}</div></div>${derived?`<details class="result-card derived-evidence"><summary>Checks and conventions</summary>${derived.checks.map(c=>`<div class="check-row"><span>✓</span>${esc(c)}</div>`).join('')}<p>APS boundary orientation gives w = n−m, the negative of the TT Surface panel’s convention. Punctures have n = 0. This implementation constructs a ribbon-cycle basis and computes intersections by contracting a spanning tree; see Methods & scope for the algorithm and validation.</p></details>`:''}`;
 $('#compute-derived').onclick=async()=>{setBusy(true);$('#compute-derived').disabled=true;try{derived=await call('derived',{quiver:q});if(report&&!dirty)report.derived=derived;if(tab==='derived')renderDerived();save()}catch(e){if($('#derived-output'))$('#derived-output').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{setBusy(false);if($('#compute-derived'))$('#compute-derived').disabled=validate(q).length>0;if($('#compare-derived'))$('#compare-derived').disabled=!others.length||validate(q).length>0}};
 $('#compare-derived').onclick=async()=>{const other=algebras.find(a=>a.id===$('#compare-target').value);if(!other)return;const left={id:activeId,name:q.name,quiver:clone(q),characteristic},right={id:other.id,name:other.q.name,quiver:clone(other.q),characteristic:other.characteristic};setBusy(true);$('#compare-derived').disabled=true;try{const result=await call('compareDerived',{left:left.quiver,right:right.quiver,leftCharacteristic:characteristic,rightCharacteristic:other.characteristic});comparison={left,right,result};if(result.left){derived=result.left;if(report&&!dirty)report.derived=derived;other.derived=result.right;if(other.report&&!other.dirty)other.report.derived=result.right}if(tab==='derived')renderDerived();save()}catch(e){if($('#comparison-output'))$('#comparison-output').innerHTML=`<div class="notice error">Comparison unavailable: ${esc(e.message)}</div>`}finally{setBusy(false);if($('#compare-derived'))$('#compare-derived').disabled=false;if($('#compute-derived'))$('#compute-derived').disabled=validate(q).length>0}};
 if($('#derived-json'))$('#derived-json').onclick=()=>download('gentle-derived.json',JSON.stringify({quiver:q,characteristic,derived,comparison:currentComparison()},null,2),'application/json');
 if($('#derived-tex'))$('#derived-tex').onclick=()=>download('gentle-derived.tex',latexDerivedReport(q,derived,currentComparison()),'application/x-tex');
}
function comparisonHTML(c){const r=c.result;return `<div class="notice comparison-result"><strong>${r.equivalent===true?'Derived equivalent':r.equivalent===false?'Not derived equivalent':'Different ground fields'}</strong><p>${esc(c.left.name||'Left algebra')} ↔ ${esc(c.right.name||'Right algebra')}</p><p>${esc(r.reason)}</p></div>${r.left?`<details class="derived-evidence"><summary>Compare the complete signatures</summary><div class="operation-grid"><div><h3>${esc(c.left.name||'Left algebra')}</h3>${derivedCards(r.left)}</div><div><h3>${esc(c.right.name||'Right algebra')}</h3>${derivedCards(r.right)}</div></div></details>`:''}`}

function renderAllDegrees(){
 $('#results').innerHTML=`<div class="notice">A finite description of all degrees, not an extrapolation from the displayed table. Families follow Theorem 3.12; the ring presentation follows Theorem 5.8, with the characteristic-two dual-number exception treated separately.</div><div class="result-card"><h3>Homogeneous cohomology families</h3><div class="table-wrap"><table><thead><tr><th>Family</th><th>Class</th><th>Degrees</th><th>Description</th></tr></thead><tbody>${report.families.map(f=>`<tr><td>H${esc(f.type)}</td><td>${esc(f.name)}${f.multiplicity>1?` (×${f.multiplicity})`:''}</td><td>${f.step?`${f.degree} + ${f.step}j, j ≥ 0`:f.degree}</td><td>${esc(f.description)}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:15px">Families III and V (cocomplete permitted circuits) are absent for finite-dimensional inputs. In a circuit family tᵢ is a polynomial generator and sᵢ is obtained from an arrow derivation times tᵢ; sᵢ is not an additional ring generator.</p></div><div class="result-card" style="margin-top:18px"><h3>Query any degree from the formulas</h3><div class="operation-controls"><label for="formula-degree">Degree</label><input id="formula-degree" type="number" min="0" max="100000" value="100" style="width:110px"><button id="formula-query" class="small-button">Evaluate dimensions</button></div><div id="formula-result" aria-live="polite"></div><p>Queries up to degree 100000 use complete-circuit counts, including the characteristic-dependent Connes coefficients. No large tensor complex is needed.</p></div><div class="result-card" style="margin-top:18px"><h3>Full cohomology ring presentation</h3><p>For a disconnected quiver, take the direct product of the component rings. Generator names here refer to the paper’s representatives and are separate from the row-reduced basis names in Operations.</p>${report.ring.map((r,i)=>`<details class="basis-card" open style="margin-top:15px"><summary>Component ${i+1} · vertices ${r.vertices.map(esc).join(', ')}</summary><p style="margin-top:12px">${esc(r.description)}</p><div class="table-wrap"><table><thead><tr><th>Generator</th><th>Degree</th></tr></thead><tbody>${r.generators.map(g=>`<tr><td>${esc(g.name)}</td><td>${g.degree}</td></tr>`).join('')||'<tr><td>Only the unit: this ring is k.</td><td>0</td></tr>'}</tbody></table></div>${r.exceptional?'':`<p style="margin-top:12px">Quadratic monomials not killed by the presentation:</p><div class="pill-list">${r.allowedProducts.map(x=>`<span class="pill">${esc(x)}</span>`).join('')||'<span class="micro">None; every product of two listed generators is zero.</span>'}</div>`}${r.equalities.length?`<p style="margin-top:12px">Additional identifications:</p>${r.equalities.map(x=>`<p class="math">${esc(x)}</p>`).join('')}`:''}</details>`).join('')}</div><div class="result-card" style="margin-top:18px"><h3>All homology and Connes families</h3><p>There is one degree-zero idempotent class per vertex, killed by B. For each complete primitive circuit C of length r, and every k ≥ 1 with (−1)<sup>(kr+1)r</sup> = 1 in k, there are classes x<sub>C,k</sub> in degree kr−1 and y<sub>C,k</sub> in degree kr. Their Connes differential is B(x<sub>C,k</sub>) = k y<sub>C,k</sub> and B(y<sub>C,k</sub>) = 0. These are all the homology classes. Use k modulo the chosen characteristic.</p><p style="margin-top:10px">The de Rham classes are the vertex classes, together with x<sub>C,k</sub> and y<sub>C,k</sub> when k vanishes in the field. Cyclic homology in degree n is coker B<sub>n−1</sub> ⊕ ⨁<sub>j≥1</sub> Hᵈᴿ<sub>n−2j</sub>; terms in negative degrees vanish.</p></div>`;
 $('#formula-query').onclick=async()=>{const n=Number($('#formula-degree').value);try{const r=await call('formula',{degree:n});(report.formulaQueries??=[]).push(r);if($('#formula-result'))$('#formula-result').innerHTML=`<div class="notice">Degree ${r.degree}: dim HHⁿ = ${r.co}, dim HHₙ = ${r.hh}, dim HCₙ = ${r.hc}, dim Hᵈᴿₙ = ${r.deRham}, rank Bₙ = ${r.bRank}.</div>`}catch(e){if($('#formula-result'))$('#formula-result').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}};
}
function renderSurface(){const r=report&&!dirty?report.structure.ribbon:ribbonFromQuiver(q),types=surfaceComponents(q);$('#results').innerHTML=`${surfaceFigures(types)}<div class="metric-grid"><div class="metric"><div class="metric-label">Total genus</div><div class="metric-value">${r.genus}</div><div class="metric-foot">${r.components} surface component(s)</div></div><div class="metric"><div class="metric-label">Boundary components</div><div class="metric-value">${r.boundaries.length}</div><div class="metric-foot">Including unmarked boundaries</div></div><div class="metric"><div class="metric-label">Marked points</div><div class="metric-value">${r.markedPoints}</div><div class="metric-foot">Vertices of the ribbon graph</div></div><div class="metric"><div class="metric-label">Surface Euler characteristic</div><div class="metric-value">${r.euler}</div><div class="metric-foot">|G₀| − |G₁| = 2c − 2g − b</div></div></div><div class="overview-bottom"><div class="result-card"><h3>Boundary and winding data</h3><div class="table-wrap"><table><thead><tr><th>Boundary</th><th>Marked points n</th><th>Forbidden length m</th><th>Winding m−n</th><th>Edge walk</th></tr></thead><tbody>${r.boundaries.map((b,i)=>`<tr><td>${i+1}</td><td>${b.markedPoints}</td><td>${b.forbiddenLength}</td><td>${b.winding}</td><td>${b.edgeWalk.map(esc).join(' → ')}</td></tr>`).join('')}</tbody></table></div></div><div class="result-card"><h3>Avella-Alaminos–Geiss invariant</h3>${r.aag.map(a=>`<p class="math">φ<sub>A</sub>(${a.pair.join(', ')}) = ${a.multiplicity}</p>`).join('')}<p style="margin-top:12px">All other entries vanish. Each boundary contributes one pair (marked points, total forbidden length). This describes the marked surface combinatorially; the diagrams above show standard models of its surface components.</p></div></div><div class="overview-bottom"><div class="result-card"><h3>Ribbon vertices and cyclic orders</h3><p>Each nontrivial ribbon vertex is a maximal permitted path. Trivial paths supply missing incidences. Repeated visits are distinct half-edges. The marked sector closes each listed linear order.</p><div class="table-wrap"><table><thead><tr><th>G vertex</th><th>Thread</th><th>Ordered incident edges</th></tr></thead><tbody>${r.threads.map((t,i)=>`<tr><td>${i+1}</td><td>${esc(t.label)}</td><td>${t.visits.map(esc).join(' → ')}</td></tr>`).join('')}</tbody></table></div></div><div class="result-card"><h3>Ribbon edges</h3><p>One edge for each vertex of Q; each has exactly two half-edges.</p><div class="table-wrap"><table><thead><tr><th>Q vertex / G edge</th><th>G endpoints</th></tr></thead><tbody>${r.edges.map(e=>`<tr><td>${esc(e.label)}</td><td>${e.ends.map(i=>i+1).join(' ↔ ')}</td></tr>`).join('')}</tbody></table></div></div></div><div class="notice" style="margin-top:18px">Unmarked boundaries correspond to complete relation circuits. A boundary with one marked point supplies a cohomology generator in degree m; an unmarked boundary of length r supplies one in degree r if r is even or char k = 2, and otherwise in degree 2r. See Theorem 7.1 and Corollary 7.2. Finite-dimensional inputs have no G-punctures from infinite permitted paths.</div>`;mountSurfaceFigures(types)}
function renderLie(){$('#results').innerHTML=`<div class="result-card"><h3>The Lie algebra HH¹(A)</h3><p>Compute its full bracket table, center, and derived series using exact cohomology classes. Indices refer to the HH¹ basis in the Cohomology tab.</p><button id="lie-query" class="primary-button operation-run">Compute Lie structure <span>→</span></button><div id="lie-result" style="margin-top:18px" aria-live="polite"></div></div>`;$('#lie-query').onclick=async()=>{const b=$('#lie-query');b.disabled=true;setBusy(true);try{const r=await call('lieStructure');report.lie=r;if($('#lie-result'))$('#lie-result').innerHTML=`<div class="notice">Dimension ${r.dimension} · center dimension ${r.centerDimension} · ${r.solvable?'solvable':'not solvable'}<br>Derived-series dimensions: ${r.derived.join(' → ')}${r.solvable?'':' → … (stable)'}</div><div class="table-wrap"><table><thead><tr><th>[−,−]</th>${r.table.map((_,i)=>`<th>h¹<sub>${i+1}</sub></th>`).join('')}</tr></thead><tbody>${r.table.map((row,i)=>`<tr><th>h¹<sub>${i+1}</sub></th>${row.map(cs=>`<td>${formula(cs,'co',1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}catch(e){if($('#lie-result'))$('#lie-result').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}finally{b.disabled=false;setBusy(false)}}}
function renderFormulaOnly(){$('#results').innerHTML=`<div class="notice">The exact circuit formulas computed the dimensions below. ${esc(report.limitation)}<br>Bar representatives and operations on their coordinates are unavailable for this range. Reduce the degree and recompute, or use Structure to query a group in the smaller Bardzell complex.</div><div class="result-card"><h3>Exact dimensions</h3>${tableRows()}<h3 style="margin-top:18px">Connes and de Rham dimensions</h3><div class="table-wrap"><table><thead><tr><th>n</th><th>rank Bₙ</th><th>dim Hᵈᴿₙ</th></tr></thead><tbody>${report.rows.map(x=>`<tr><td>${x.degree}</td><td>${x.connesRank}</td><td>${x.deRham}</td></tr>`).join('')}</tbody></table></div></div>`}
